package com.catpuzzle.assistant; import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.media.projection.MediaProjectionManager;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.widget.*; public class MainActivity extends Activity{static final int REQ=501;TextView st; public void onCreate(Bundle b){super.onCreate(b);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},1); LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(36,36,36,36);r.setBackgroundColor(Color.rgb(243,246,244));TextView t=new TextView(this);t.setText("Cat Puzzle Assistant 1.1.0");t.setTextSize(26);t.setTextColor(Color.rgb(18,61,47));r.addView(t);st=new TextView(this);r.addView(st);Button o=b("1. Разрешить поверх игры");o.setOnClickListener(v->{if(!Settings.canDrawOverlays(this))startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));else startService(new Intent(this,OverlayService.class));});r.addView(o);Button c=b("2. Разрешить захват экрана");c.setOnClickListener(v->{MediaProjectionManager m=(MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE);startActivityForResult(m.createScreenCaptureIntent(),REQ);});r.addView(c);Button a=b("3. Включить автонажатия");a.setOnClickListener(v->startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS)));r.addView(a);Button s=b("Запустить помощник");s.setOnClickListener(v->{if(Settings.canDrawOverlays(this))startService(new Intent(this,OverlayService.class));moveTaskToBack(true);});r.addView(s);TextView info=new TextView(this);info.setText("▶ — автоходы по одному с пересчётом после каждого действия\n1 — один безопасный ход\n× — показать/скрыть крестик\nДолгое ▶ — скорость: спокойно / обычно / быстро\nПанель можно перетаскивать.");info.setTextSize(16);info.setPadding(0,30,0,0);r.addView(info);setContentView(r);refresh();} Button b(String x){Button b=new Button(this);b.setText(x);b.setAllCaps(false);return b;} void refresh(){if(st!=null)st.setText("Overlay: "+(Settings.canDrawOverlays(this)?"готов":"нет")+"  Захват: "+(FrameStore.captureReady?"готов":"нет")+"  Авто: "+(TapAccessibilityService.instance!=null?"готов":"нет"));} protected void onResume(){super.onResume();refresh();} protected void onActivityResult(int q,int res,Intent d){super.onActivityResult(q,res,d);if(q==REQ&&res==RESULT_OK&&d!=null){Intent i=new Intent(this,CaptureService.class);i.putExtra("code",res);i.putExtra("data",d);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);if(Settings.canDrawOverlays(this))startService(new Intent(this,OverlayService.class));new Handler().postDelayed(this::refresh,600);}}}